import{_ as t,c as r,e as i,i as l}from"./app-02424545.js";const a={},d=l('<h1 id="🎋-2026-端午节珠海·澳门四日三晚旅游攻略" tabindex="-1"><a class="header-anchor" href="#🎋-2026-端午节珠海·澳门四日三晚旅游攻略" aria-hidden="true">#</a> 🎋 2026 端午节珠海·澳门四日三晚旅游攻略</h1><blockquote><p>出行时间：2026年6月19日（周五）— 6月22日（周一）<br> 酒店：第2-4天住 珠海香洲区紫荆路附近<br> 天气提示：6月珠海进入夏季，气温28-33°C，湿热多雨，出行务必备好防晒、雨具和防蚊液。</p></blockquote><hr><h2 id="📋-行程总览" tabindex="-1"><a class="header-anchor" href="#📋-行程总览" aria-hidden="true">#</a> 📋 行程总览</h2><table><thead><tr><th>天数</th><th>日期</th><th>主要行程</th><th>住宿</th></tr></thead><tbody><tr><td>第一天</td><td>6月19日（周五）</td><td>到达珠海 → 拱北口岸过关 → 澳门游览 → 回珠海</td><td>澳门或拱北附近酒店（待定）</td></tr><tr><td>第二天</td><td>6月20日（周六）</td><td>情侣路沿线 + 日月贝 + 珠海渔女 + 夜市</td><td>香洲区紫荆路附近酒店</td></tr><tr><td>第三天</td><td>6月21日（周日）</td><td>圆明新园 + 北山大院 + 香洲区觅食</td><td>香洲区紫荆路附近酒店</td></tr><tr><td>第四天</td><td>6月22日（周一）</td><td>香炉湾沙滩 + 野狸岛 + 返程</td><td>—</td></tr></tbody></table><hr><h2 id="🗺️-第一天-6月19日-抵达珠海-·-游澳门" tabindex="-1"><a class="header-anchor" href="#🗺️-第一天-6月19日-抵达珠海-·-游澳门" aria-hidden="true">#</a> 🗺️ 第一天（6月19日）：抵达珠海 · 游澳门</h2><blockquote><p>建议上午或中午抵达珠海，轻装前往澳门，傍晚返回珠海。</p></blockquote><h3 id="上午-抵达-过关澳门" tabindex="-1"><a class="header-anchor" href="#上午-抵达-过关澳门" aria-hidden="true">#</a> 上午：抵达 &amp; 过关澳门</h3><p><strong>酒店推荐（第一晚，拱北口岸附近，过关方便）</strong></p><ul><li><strong>拱北皇冠假日酒店</strong> — 紧邻口岸，设施完善，适合快进快出</li><li><strong>珠海皇悦酒店</strong>（拱北区域）— 性价比高，步行可达口岸</li><li><strong>速8酒店（珠海拱北店）</strong> — 预算友好型，位置佳</li></ul><blockquote><p>第一天行程以澳门为主，建议入住拱北口岸步行距离内的酒店，方便当晚出关回来。</p></blockquote><p><strong>拱北口岸过关</strong></p><ul><li>地址：珠海市香洲区友谊路与迎宾南路交叉口</li><li>开放时间：06:00 — 次日01:00</li><li>🔴 端午节人流量大，建议10:00前过关，避开早高峰（07:30-10:30）</li><li>过关需携带：港澳通行证（回乡证） + 有效澳门签注</li><li>关口旧厅正在改造，现走两侧新厅，稍慢，预留30-60分钟过关时间</li></ul><h3 id="下午-澳门经典打卡" tabindex="-1"><a class="header-anchor" href="#下午-澳门经典打卡" aria-hidden="true">#</a> 下午：澳门经典打卡</h3><p><strong>路线建议（步行+巴士，约6小时）</strong></p><ol><li><strong>大三巴牌坊</strong>（圣保罗教堂遗址）— 澳门地标，中西合璧，是必拍之地</li><li><strong>大炮台 &amp; 澳门博物馆</strong>（大三巴旁，门票MOP15）— 俯瞰老城风光</li><li><strong>恋爱·巷</strong>（Rua do Amor）— 粉色浪漫小巷，INS网红打卡</li><li><strong>议事亭前地</strong>（澳门中心广场）— 欧式建筑群，免费开放</li><li><strong>新马路</strong>（亚马喇前地附近）— 澳门老字号集中地，可顺路觅食</li></ol><h3 id="晚餐-澳门觅食-18-00-19-00" tabindex="-1"><a class="header-anchor" href="#晚餐-澳门觅食-18-00-19-00" aria-hidden="true">#</a> 晚餐：澳门觅食（18:00-19:00）</h3><ul><li><strong>协利记猪扒包</strong>（新口岸附近）— 猪扒包是澳门必吃国民小吃</li><li><strong>大利来记</strong>（氹仔）— 澳门最著名猪扒包老字号</li><li><strong>安德鲁蛋挞</strong>（路环分店）— 蛋挞发源地，必吃</li><li><strong>葡挞 + 葡式咖啡</strong> — 顺路在任意饼店购入</li></ul><h3 id="晚上-返回珠海" tabindex="-1"><a class="header-anchor" href="#晚上-返回珠海" aria-hidden="true">#</a> 晚上：返回珠海</h3><ul><li>建议19:30-20:30从澳门出关，经拱北口岸回珠海</li><li>入境高峰期为18:00-21:00，需预留等待时间</li><li>回到拱北可乘出租车/滴滴前往当晚酒店</li><li>拱北口岸附近夜市觅食 — 如果在澳门没吃饱，拱北商圈附近有很多宵夜摊和夜宵餐厅，炒粉、肠粉、海鲜粥随便点，价格比澳门实惠很多。</li><li>莲花路夜逛 — 拱北莲花路步行街是珠海著名的购物夜市街，21:00前都还热闹，可以买买葡式饼干、澳门手信、零食，逛起来轻松。价格比澳门店便宜，适合扫货。</li></ul><hr><h2 id="🌊-第二天-6月20日-情侣路全线漫游" tabindex="-1"><a class="header-anchor" href="#🌊-第二天-6月20日-情侣路全线漫游" aria-hidden="true">#</a> 🌊 第二天（6月20日）：情侣路全线漫游</h2><blockquote><p>住：香洲区紫荆路酒店。端午节正日，下午景色最美，建议避开正午高温。</p></blockquote><h3 id="上午-珠海渔女-爱情邮局-09-00-12-00" tabindex="-1"><a class="header-anchor" href="#上午-珠海渔女-爱情邮局-09-00-12-00" aria-hidden="true">#</a> 上午：珠海渔女 + 爱情邮局（09:00-12:00）</h3><ol><li><p><strong>珠海渔女雕塑</strong>（香炉湾北侧）</p><ul><li>珠海标志性地标，雕像高8.7米，可在此打卡留念</li><li>乘坐9路公交到&quot;珠海渔女站&quot;即可</li></ul></li><li><p><strong>爱情邮局 &amp; 灯塔</strong>（情侣路中段）</p><ul><li>可在此寄出一张专属情侣路明信片，附近有复古灯塔可拍照</li></ul></li><li><p><strong>城市客厅</strong>（海滨泳场旁）</p><ul><li>海景广场，是情侣路人气最旺的区域</li></ul></li></ol><h3 id="午餐-12-00-13-30" tabindex="-1"><a class="header-anchor" href="#午餐-12-00-13-30" aria-hidden="true">#</a> 午餐（12:00-13:30）</h3><ul><li><strong>夏湾夜市</strong> 周边午市餐厅 — 海鲜粥、肠粉、肠粉等广式早午餐</li><li><strong>888美食街</strong>（香洲区）— 聚集各类本地小吃，价格实惠</li></ul><h3 id="下午-日月贝-野狸岛-14-00-18-00" tabindex="-1"><a class="header-anchor" href="#下午-日月贝-野狸岛-14-00-18-00" aria-hidden="true">#</a> 下午：日月贝 + 野狸岛（14:00-18:00）</h3><ol><li><strong>野狸岛公园</strong>（情侣路南段）— 免费开放的海边公园，绿树成荫，海风习习</li><li><strong>日月贝大剧院</strong>（野狸岛旁）— 外观免费参观，造型如贝壳，建议<strong>19:00后</strong>看夜景灯光</li><li><strong>香炉湾沙滩</strong>（城市阳台）— 情侣路最美沙滩之一，可在海边散步、看海</li></ol><blockquote><p>⚠️ 端午节正值夏季，14:00-16:00紫外线极强，建议室内休息或提早至沙滩边带伞遮阳</p></blockquote><h3 id="傍晚-城市阳台日落-18-00-20-00" tabindex="-1"><a class="header-anchor" href="#傍晚-城市阳台日落-18-00-20-00" aria-hidden="true">#</a> 傍晚：城市阳台日落（18:00-20:00）</h3><ul><li>香炉湾沙滩处看珠海日落是一大享受，落日约在19:00左右</li><li>带一杯椰汁/冷饮，在海边吹风放空</li></ul><h3 id="晚餐-海鲜大餐-20-00" tabindex="-1"><a class="header-anchor" href="#晚餐-海鲜大餐-20-00" aria-hidden="true">#</a> 晚餐：海鲜大餐（20:00）</h3><ul><li><strong>湾仔海鲜街</strong> — 珠海最著名的海鲜街，各类新鲜海产，可自选自煮</li><li><strong>蛇平饭店</strong>（非遗美食）— 招牌海沙煨鸡、鲍汁海参，老字号</li><li><strong>万山楼海鲜酒家</strong> — 性价比高，本地人常去</li></ul><hr><h2 id="🏛️-第三天-6月21日-历史文化-本地市井" tabindex="-1"><a class="header-anchor" href="#🏛️-第三天-6月21日-历史文化-本地市井" aria-hidden="true">#</a> 🏛️ 第三天（6月21日）：历史文化 + 本地市井</h2><blockquote><p>端午节假期最后一天，人流较多，建议上午早出门。</p></blockquote><h3 id="上午-圆明新园-09-00-12-00" tabindex="-1"><a class="header-anchor" href="#上午-圆明新园-09-00-12-00" aria-hidden="true">#</a> 上午：圆明新园（09:00-12:00）</h3><ul><li><strong>地址</strong>：珠海市九洲大道石林山下</li><li><strong>门票</strong>：免费（需提前预约）</li><li>集皇家园林、江南园林与西洋建筑于一体，景观丰富，适合慢逛</li><li>夏季建议上午去，带好遮阳帽和防晒霜</li><li>附近有九洲城商圈，可顺路逛</li></ul><h3 id="午餐-北山大院附近-12-30-14-00" tabindex="-1"><a class="header-anchor" href="#午餐-北山大院附近-12-30-14-00" aria-hidden="true">#</a> 午餐：北山大院附近（12:30-14:00）</h3><ul><li><strong>北山历史文化名村</strong> — 漫步百年古村，探访岭南传统民居</li><li><strong>北山茶果</strong>（非遗小吃）— 在北山村可找到传统茶果摊</li><li><strong>廿四味饭堂</strong> — 珠海本地家常菜，口碑极好</li></ul><h3 id="下午-香洲区市井逛逛-14-30-18-00" tabindex="-1"><a class="header-anchor" href="#下午-香洲区市井逛逛-14-30-18-00" aria-hidden="true">#</a> 下午：香洲区市井逛逛（14:30-18:00）</h3><ol><li><strong>香洲埠历史文化街区</strong> — 老珠海风貌，临海而建，步行游览约1小时</li><li><strong>华发商都 / 印象城</strong> — 下午避暑佳选，室内购物中心，可买伴手礼</li><li><strong>拱北莲花路</strong> — 澳门风情购物街，适合淘货买纪念品</li></ol><h3 id="晚餐-夏湾夜市-19-00" tabindex="-1"><a class="header-anchor" href="#晚餐-夏湾夜市-19-00" aria-hidden="true">#</a> 晚餐：夏湾夜市（19:00）</h3><ul><li>珠海著名夜市，汇聚烧烤、炒粉、海鲜、糖水等夜宵摊</li><li>端午节可寻找当地粽子摊，尝尝珠海口味的粽子</li><li>推荐：生蚝、濑尿虾、花螺、椰子鸡</li></ul><hr><h2 id="🌅-第四天-6月22日-轻松收尾-·-踏上归途" tabindex="-1"><a class="header-anchor" href="#🌅-第四天-6月22日-轻松收尾-·-踏上归途" aria-hidden="true">#</a> 🌅 第四天（6月22日）：轻松收尾 · 踏上归途</h2><blockquote><p>建议当天买早点出发的交通，避开节后人流高峰。</p></blockquote><h3 id="上午-香炉湾或海滨公园-09-00-11-00" tabindex="-1"><a class="header-anchor" href="#上午-香炉湾或海滨公园-09-00-11-00" aria-hidden="true">#</a> 上午：香炉湾或海滨公园（09:00-11:00）</h3><ul><li>最后一次吹海风，在海滨公园晨跑/散步</li><li>拍几张珠海早晨的照片留作纪念</li></ul><h3 id="午餐-11-30-12-30" tabindex="-1"><a class="header-anchor" href="#午餐-11-30-12-30" aria-hidden="true">#</a> 午餐（11:30-12:30）</h3><ul><li><strong>强记湛江鸡饭店</strong> — 白切鸡饭是珠海必吃，价格实惠</li><li><strong>大赤坎肥仔强烧味海鲜</strong> — 烧腊+本地菜，性价比佳</li></ul><h3 id="下午-返程" tabindex="-1"><a class="header-anchor" href="#下午-返程" aria-hidden="true">#</a> 下午：返程</h3><ul><li>珠海高铁站（珠海站，毗邻拱北口岸）乘高铁返程</li><li>机场：珠海金湾机场，距市区约40分钟车程，提前预留时间</li></ul><hr><h2 id="🚌-交通指引" tabindex="-1"><a class="header-anchor" href="#🚌-交通指引" aria-hidden="true">#</a> 🚌 交通指引</h2><h3 id="珠海市区内出行" tabindex="-1"><a class="header-anchor" href="#珠海市区内出行" aria-hidden="true">#</a> 珠海市区内出行</h3><ul><li><strong>公交</strong>：情侣路沿线有9路、11路等公交；圆明新园可坐至九洲城附近换乘</li><li><strong>滴滴/打车</strong>：端午节期间高峰期叫车稍慢，建议提前叫车</li><li><strong>共享单车</strong>：香洲区单车覆盖广，情侣路沿线骑行非常舒适（建议傍晚骑行）</li></ul><h3 id="珠海-↔-澳门过关" tabindex="-1"><a class="header-anchor" href="#珠海-↔-澳门过关" aria-hidden="true">#</a> 珠海 ↔ 澳门过关</h3><ul><li><strong>拱北口岸</strong>（推荐）：步行过关，06:00-次日01:00，端午节人多排队需预留时间</li><li><strong>青茂口岸</strong>：全天24小时，位于香洲区，适合不住拱北区域的游客</li><li><strong>横琴口岸</strong>：全天24小时，可达澳门氹仔/路环区域</li></ul><hr><h2 id="🍜-珠海必吃美食清单" tabindex="-1"><a class="header-anchor" href="#🍜-珠海必吃美食清单" aria-hidden="true">#</a> 🍜 珠海必吃美食清单</h2><table><thead><tr><th>美食</th><th>推荐地点</th><th>特色</th></tr></thead><tbody><tr><td>生蚝</td><td>湾仔海鲜街 / 横琴生蚝烧烤摊</td><td>横琴本地生蚝，肉质鲜嫩</td></tr><tr><td>海鲜粥</td><td>夏湾夜市 / 888美食街</td><td>现熬鲜粥，广式口味</td></tr><tr><td>白切鸡饭</td><td>强记湛江鸡饭店</td><td>招牌菜，皮脆肉嫩</td></tr><tr><td>海沙煨鸡</td><td>蛇平饭店（非遗）</td><td>独特烹饪工艺，非遗美食</td></tr><tr><td>糖水甜品</td><td>全城糖水铺</td><td>姜撞奶、芒果布丁、双皮奶</td></tr><tr><td>端午粽子</td><td>夏湾夜市 / 本地糕饼店</td><td>应节食品，咸肉粽/豆沙粽</td></tr><tr><td>猪扒包</td><td>澳门大利来记</td><td>澳门国民小吃</td></tr><tr><td>葡式蛋挞</td><td>澳门安德鲁饼店</td><td>酥脆奶香，蛋挞发源地</td></tr></tbody></table><hr><h2 id="🎒-出行必备清单" tabindex="-1"><a class="header-anchor" href="#🎒-出行必备清单" aria-hidden="true">#</a> 🎒 出行必备清单</h2><ul><li>港澳通行证（回乡证）+ 澳门有效签注（提前自助签注）</li><li>防晒霜（SPF50+）、防晒帽、墨镜</li><li>雨具（折叠伞或轻便雨衣，6月多阵雨）</li><li>防蚊液（海边蚊虫较多）</li><li>港澳零钱/澳门元（澳门部分小店不收微信/支付宝）</li><li>人民币现金（部分珠海夜市摊位不支持扫码）</li><li>充电宝（拍照导航耗电快）</li></ul><hr><h2 id="💡-实用提示" tabindex="-1"><a class="header-anchor" href="#💡-实用提示" aria-hidden="true">#</a> 💡 实用提示</h2><ol><li><p><strong>端午节旺季注意事项</strong>：景区、餐厅和口岸人流量大，建议各景点提前网上预约/预订，餐厅尽量错峰用餐（12:00之前或13:30之后）。</p></li><li><p><strong>拱北口岸过关技巧</strong>：错开高峰期（07:30-10:30及18:00-21:00），建议上午10:30后过关澳门，傍晚17:30前返回，等待时间最短。</p></li><li><p><strong>天气应对</strong>：6月珠海高温潮湿，室外活动建议安排在上午09:00前或傍晚17:00后，中午可安排室内景点（博物馆、圆明新园室内展区、购物中心）。</p></li><li><p><strong>住宿提醒</strong>：端午假期珠海酒店可能涨价，尽早预订，香洲区紫荆路附近交通便利，距情侣路、夏湾夜市均在合理距离。</p></li><li><p><strong>澳门购物</strong>：澳门免税商品（化妆品、巧克力、药材等）性价比高，可带小购物袋入境澳门购物。</p></li></ol><hr><p><em>本攻略基于2026年6月实际情况规划，端午节正值旺季，各景点票务、餐厅营业时间等请出发前再次确认。祝旅途愉快！🎋</em></p>',72),e=[d];function h(n,o){return r(),i("div",null,e)}const g=t(a,[["render",h],["__file","zhuhai.html.vue"]]);export{g as default};
